C=np.c_[np.ones_like(P),P,P**2,P**3]
y=dP_dt
best=None
for a in np.linspace(0.05,5,400):
  for form in [0,1]:
    extra=np.sin(a*P) if form==0 else np.exp(-a*P**2)
    B=np.c_[C,extra]
    c,_,_,_=np.linalg.lstsq(B,y,rcond=None)
    s=np.sum((y-B@c)**2)
    if best is None or s<best[0]: best=(s,a,form,c)
print(best[0]/np.sum((y-y.mean())**2), best[1:3], best[3])
